'use strict';
const $ = s => document.querySelector(s);
const KEY='grammys-kitchen-v1';
const seed=[{"id":"original-1","title":"Orange Juice Cookies","category":"Cookies","temperature":"350° (scale not printed)","time":"10 minutes","ingredients":["2 cups sugar","1 cup margarine","2 eggs","1 cup milk","½ can frozen orange juice concentrate, thawed — can size to verify","4½ cups flour","2 teaspoons baking powder","Frosting: a little melted butter (quantity not specified)","Frosting: a little thawed orange juice (quantity not specified)","Frosting: powdered sugar (quantity not specified)"],"steps":["Cream the first three ingredients: sugar, margarine, and eggs.","Add the remaining dough ingredients gradually.","Drop onto cookie sheets.","Bake at 350° for 10 minutes. The printed recipe does not state the temperature scale.","When cool, frost with a little melted butter, a little thawed orange juice, and powdered sugar. Frosting quantities are not specified."],"notes":"Transcribed from the supplied recipe photo. The handwritten note reads “1 batch = 100 cookies.” The owner clarified that the orange juice amount means half a can of concentrate. Can size remains unspecified; verify it before cooking. The printed temperature has no scale. Frosting amounts are given only as “a little”; powdered sugar has no quantity.","unverified":true,"favorite":false,"photo":"data:image/jpeg;base64,","yield":"100 cookies per batch (handwritten note)"},{"id":"original-2","title":"Quick Mix Spritz","category":"Cookies","temperature":"375° (scale not printed)","time":"10–12 minutes","ingredients":["2¼ cups flour","¾ cup sugar","¼ teaspoon baking powder","½ teaspoon salt","1 cup shortening","1 egg","1 tablespoon vanilla","Food coloring (quantity not specified)"],"steps":["Cream shortening, sugar, and egg. The printed directions say “eggs,” while the ingredient list specifies 1 egg.","Gradually add dry ingredients.","When you can form a ball, add food coloring.","Press cookies onto cookie sheet.","Bake at 375° for 10–12 minutes. The printed recipe does not state the temperature scale."],"notes":"Transcribed from the supplied recipe photo. Makes 5 dozen. The ingredient list specifies 1 tablespoon vanilla; the directions do not state when to add it. Verify that step before cooking. The ingredient list says 1 egg; the directions use the plural “eggs.” The printed temperature has no scale. No food coloring amount is specified.","unverified":true,"favorite":false,"photo":"data:image/jpeg;base64,","yield":"5 dozen"}];
let recipes=structuredClone(seed), onlyFavorites=false, editingId=null, currentId=null, selectedPhoto='', installPrompt;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,5000)}
function escapeHTML(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function safePhoto(s){return typeof s==='string' && /^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(s) && s.length<4000000?s:''}
function validate(data){if(!Array.isArray(data)||data.length>500)throw Error('Choose a valid backup containing up to 500 recipes.');const ids=new Set();return data.map(r=>{if(!r||typeof r.title!=='string'||!r.title.trim()||!Array.isArray(r.ingredients)||!Array.isArray(r.steps))throw Error('The backup contains an invalid recipe.');let id=typeof r.id==='string'?r.id:crypto.randomUUID();if(ids.has(id))throw Error('The backup has duplicate recipe IDs.');ids.add(id);const str=v=>typeof v==='string'?v.slice(0,20000):'';return {id,title:str(r.title).slice(0,120),category:str(r.category).slice(0,60),yield:str(r.yield),temperature:str(r.temperature),time:str(r.time),ingredients:r.ingredients.slice(0,500).map(str),steps:r.steps.slice(0,500).map(str),notes:str(r.notes),unverified:r.unverified!==false,favorite:!!r.favorite,photo:safePhoto(r.photo)}})}
let storageBroken=false;
try{const saved=localStorage.getItem(KEY);if(saved)recipes=validate(JSON.parse(saved))}catch{storageBroken=true;toast('Saved data could not be read. Export a backup before making changes.');}
// Upgrade only unchanged recovery placeholders; preserve edited recipes and their photos.
if (!storageBroken) {
 const upgraded=recipes.map(r=>{
  const original=seed.find(s=>s.id===r.id);
  return original && r.title===`Recipe from original photo · ${r.id==='original-1'?'1':'2'}` && !r.ingredients.length && !r.steps.length && !r.photo ? {...original,favorite:r.favorite} : r;
 });
 if(upgraded.some((r,i)=>r!==recipes[i])) {
  try {localStorage.setItem(KEY,JSON.stringify(upgraded));recipes=upgraded;} catch {toast('Could not update original recipe entries. Export a backup and check storage.');}
 }
}
function persist(next){if(storageBroken){toast('Storage could not be read. Export a backup and clear site data before editing.');return false}try{localStorage.setItem(KEY,JSON.stringify(next));recipes=next;render();return true}catch{toast('Could not save. Device storage may be full or unavailable. Export a backup and try a smaller photo.');return false}}
function render(){const previous=$('#category').value;const categories=[...new Set(recipes.map(r=>r.category).filter(Boolean))].sort();$('#category').innerHTML='<option value="">All categories</option>'+categories.map(c=>`<option value="${escapeHTML(c)}">${escapeHTML(c)}</option>`).join('');$('#category').value=categories.includes(previous)?previous:'';const q=$('#search').value.trim().toLowerCase();const filtered=recipes.filter(r=>(!onlyFavorites||r.favorite)&&(!previous||r.category===previous)&&[r.title,r.category,r.notes,...r.ingredients].join(' ').toLowerCase().includes(q));$('#count').textContent=`${filtered.length} of ${recipes.length} recipes`;$('#empty').hidden=filtered.length>0;$('#grid').innerHTML=filtered.map(r=>`<article class="card"><div class="card-top">${r.photo?`<img src="${r.photo}" alt="Recipe photo" loading="lazy">`:'✧'}</div><button class="favorite" data-action="favorite" data-id="${escapeHTML(r.id)}" aria-label="${r.favorite?'Remove from':'Add to'} favorites: ${escapeHTML(r.title)}" aria-pressed="${r.favorite}">${r.favorite?'♥':'♡'}</button><div class="card-body"><span class="tag">${escapeHTML(r.category||'Family recipe')}</span><h3>${escapeHTML(r.title)}</h3>${r.unverified?'<span class="badge">Needs verification</span>':''}<p>${escapeHTML([r.yield,r.temperature,r.time].filter(Boolean).join(' · ')||'Open to review and add recipe details.')}</p><button class="open secondary" data-action="open" data-id="${escapeHTML(r.id)}">View recipe →</button></div></article>`).join('');$('#favorites').setAttribute('aria-pressed',String(onlyFavorites));$('#favorites').textContent=onlyFavorites?'♥ Favorites':'♡ Favorites'}
function openRecipe(id){const r=recipes.find(r=>r.id===id);if(!r)return;currentId=id;$('#detail-content').innerHTML=`<div class="dialog-top"><p class="eyebrow">${escapeHTML(r.category||'FAMILY RECIPE')}</p><button class="icon close" aria-label="Close recipe">×</button></div><h2>${escapeHTML(r.title)}</h2>${r.unverified?'<p class="notice">Needs verification. Check this recipe against the original before cooking.</p>':''}<p class="muted">${escapeHTML([r.yield,r.temperature,r.time].filter(Boolean).join(' · '))}</p><div class="recipe-columns"><section><h3>Ingredients</h3>${r.ingredients.length?r.ingredients.map(i=>`<label class="ingredient"><input type="checkbox"><span>${escapeHTML(i)}</span></label>`).join(''):'<p class="muted">Awaiting the original recipe. No quantities have been assumed.</p>'}</section><section><h3>Directions</h3>${r.steps.length?'<ol>'+r.steps.map(s=>`<li>${escapeHTML(s)}</li>`).join('')+'</ol>':'<p class="muted">Awaiting verified directions.</p>'}</section></div>${r.notes?`<h3>Family notes</h3><p style="white-space:pre-wrap">${escapeHTML(r.notes)}</p>`:''}${r.photo?`<details><summary>Original recipe photo</summary><img class="scan" src="${r.photo}" alt="Original recipe photo"></details>`:''}<div class="actions"><button data-detail="edit">Edit recipe</button><button class="secondary" data-detail="favorite">${r.favorite?'♥ Saved to favorites':'♡ Save to favorites'}</button><button class="secondary" data-detail="print">Print</button><button class="text" data-detail="delete">Delete recipe</button></div>`;if(!$('#detail').open)$('#detail').showModal()}
function openEditor(id=null){editingId=id;const r=recipes.find(r=>r.id===id);const form=$('#recipe-form');form.reset();$('#form-error').textContent='';$('#editor-title').textContent=r?'Edit recipe':'Add a recipe';for(const key of ['title','category','yield','temperature','time','notes'])form.elements[key].value=r?.[key]||'';for(const key of ['ingredients','steps'])form.elements[key].value=(r?.[key]||[]).join('\n');form.elements.unverified.checked=r?.unverified??true;selectedPhoto=r?.photo||'';$('#photo-preview').src=selectedPhoto;$('#photo-preview').hidden=!selectedPhoto;$('#editor').showModal()}
$('#grid').addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b)return;const r=recipes.find(r=>r.id===b.dataset.id);if(!r)return;if(b.dataset.action==='open')openRecipe(r.id);else persist(recipes.map(x=>x.id===r.id?{...x,favorite:!x.favorite}:x))});
$('#detail').addEventListener('click',e=>{const action=e.target.closest('[data-detail]')?.dataset.detail;const r=recipes.find(r=>r.id===currentId);if(!action||!r)return;if(action==='edit'){$('#detail').close();openEditor(r.id)}if(action==='favorite'&&persist(recipes.map(x=>x.id===r.id?{...x,favorite:!x.favorite}:x)))openRecipe(r.id);if(action==='print')window.print();if(action==='delete'&&confirm(`Delete “${r.title}” from this device? Export a backup first if you want to keep it.`)&&persist(recipes.filter(x=>x.id!==r.id)))$('#detail').close()});
document.addEventListener('click',e=>{if(e.target.closest('.close'))e.target.closest('dialog').close()});
$('#add').onclick=$('#add-bottom').onclick=()=>openEditor();$('#browse').onclick=()=>$('#cookbook').scrollIntoView({behavior:'smooth'});$('#search').oninput=render;$('#category').onchange=render;$('#favorites').onclick=()=>{onlyFavorites=!onlyFavorites;render()};
let photoLoading=false;
$('#photo').onchange=async e=>{const file=e.target.files[0];if(!file)return;photoLoading=true;$('#form-error').textContent='Preparing photo…';try{if(!file.type.startsWith('image/'))throw Error('Please choose an image.');if(file.size>25000000)throw Error('Choose an image smaller than 25 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();selectedPhoto=canvas.toDataURL('image/jpeg',.8);$('#photo-preview').src=selectedPhoto;$('#photo-preview').hidden=false;$('#recipe-form').elements.removePhoto.checked=false;$('#form-error').textContent=''}catch(err){$('#form-error').textContent=err.message||'This image could not be opened. Try a JPEG or PNG.'}finally{photoLoading=false}};
$('#recipe-form').onsubmit=e=>{e.preventDefault();if(photoLoading){$('#form-error').textContent='Please wait for the photo to finish.';return}const f=e.target.elements;const title=f.title.value.trim();if(!title){$('#form-error').textContent='Enter a recipe name.';return}const existing=recipes.find(r=>r.id===editingId);const r={id:editingId||crypto.randomUUID(),title,category:f.category.value.trim(),yield:f.yield.value.trim(),temperature:f.temperature.value.trim(),time:f.time.value.trim(),notes:f.notes.value.trim(),ingredients:f.ingredients.value.split('\n').map(s=>s.trim()).filter(Boolean),steps:f.steps.value.split('\n').map(s=>s.trim()).filter(Boolean),unverified:f.unverified.checked,favorite:existing?.favorite||false,photo:f.removePhoto.checked?'':selectedPhoto};const next=existing?recipes.map(x=>x.id===editingId?r:x):[...recipes,r];if(persist(next)){$('#editor').close();toast('Recipe saved on this device.');openRecipe(r.id)}else $('#form-error').textContent='Recipe was not saved. Export a backup or try a smaller photo.'};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),recipes},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`grammys-kitchen-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup prepared. Keep the downloaded JSON file safe.')};
$('#import').onclick=()=>$('#backup-file').click();$('#backup-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20000000)throw Error('Backup must be smaller than 20 MB.');const data=JSON.parse(await file.text());if(data.version!==1)throw Error('Unsupported backup version.');const next=validate(data.recipes);if(confirm(`Replace the ${recipes.length} recipes on this device with ${next.length} recipes from the backup?`)){if(persist(next))toast('Backup restored.')}}catch(err){toast(err.message||'Unable to restore this backup.')}e.target.value=''};
$('#install').onclick=()=>$('#help').showModal();window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#native-install').hidden=false});$('#native-install').onclick=async()=>{if(!installPrompt)return;await installPrompt.prompt();installPrompt=null;$('#native-install').hidden=true};
render();
if('serviceWorker' in navigator && location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline setup unavailable. You can still use the cookbook while online.'));
